const root = $input.first().json;
const body = root.body ?? root;
const q    = root.query ?? {};
const args = body.args ?? {};
const call = body.call ?? {};
const rawFn = q.fn ?? body.name ?? '';
const fnMap = {
  'consultar_disponibilidad': 'consultar', 'crear_reserva': 'crear', 'cancelar_reserva': 'cancelar',
  'modificar_reserva': 'actualizar',
  'consultar': 'consultar', 'crear': 'crear', 'cancelar': 'cancelar',
  'modificar': 'actualizar', 'actualizar': 'actualizar'
};
const fn = fnMap[rawFn] ?? rawFn;

// ===== Detectar negocio por agent_id =====
const AGENTES = {
  'agent_5efa5c468a96d7b2c19c715460': '11111111-1111-1111-1111-111111111111', // Centre Mèdic
  'agent_4cfc376e82b5663f5b31bb3e37': '22222222-2222-2222-2222-222222222222', // Dentos
  'agent_cbd6d8af78bb572c980d8212b1': 'b4ac5f7a-e99a-4db8-8336-aef5ea4bfbf5', // Peluqueria Canina
  'agent_0eea59494eee116412bb4ee589': '8d0ce837-82a2-4d0f-bf55-95d581d7d680'  // La Tasqueta (Llívia)
};
const negocio_id = AGENTES[call.agent_id] ?? '11111111-1111-1111-1111-111111111111';

function resolverFecha(input) {
  if (!input) return '';
  let s = String(input).trim().toLowerCase();

  // números en letra -> cifra ("dentro de dos semanas", "tres dias"...)
  const numLetra = {una:1,uno:1,un:1,dos:2,tres:3,cuatro:4,cinco:5,seis:6,siete:7,ocho:8,nueve:9,diez:10};
  for (const [pal,n] of Object.entries(numLetra)) {
    s = s.replace(new RegExp('\\b'+pal+'\\b','g'), String(n));
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;

  const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
  const hoy = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate());
  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

  // "pasado mañana" ANTES que "mañana"
  if (s.includes('pasado manana') || s.includes('pasado mañana') || s.includes('dema passat') || s.includes('demà passat') ||
      s.includes('day after tomorrow') || s.includes('apres-demain') || s.includes('après-demain')) {
    const d=new Date(hoy); d.setDate(d.getDate()+2); return fmt(d);
  }
  if (s.includes('hoy') || s.includes('today') || s.includes('avui') || s.includes('aujourd')) return fmt(hoy);
  if (s.includes('manana') || s.includes('mañana') || s.includes('tomorrow') || s.includes('dema') || s.includes('demà') || s.includes('demain')) {
    const d=new Date(hoy); d.setDate(d.getDate()+1); return fmt(d);
  }

  // "en / dentro de X dias"
  let m = s.match(/(?:en|dentro de)\s+(\d+)\s*d[ií]as?/);
  if (m) { const d=new Date(hoy); d.setDate(d.getDate()+parseInt(m[1],10)); return fmt(d); }
  // "en / dentro de X semanas"
  m = s.match(/(?:en|dentro de)\s+(\d+)\s*semanas?/);
  if (m) { const d=new Date(hoy); d.setDate(d.getDate()+parseInt(m[1],10)*7); return fmt(d); }

  const dias = {
    'domingo':0,'lunes':1,'martes':2,'miercoles':3,'miércoles':3,'jueves':4,'viernes':5,'sabado':6,'sábado':6,
    'sunday':0,'monday':1,'tuesday':2,'wednesday':3,'thursday':4,'friday':5,'saturday':6,
    'diumenge':0,'dilluns':1,'dimarts':2,'dimecres':3,'dijous':4,'divendres':5,'dissabte':6,
    'dimanche':0,'lundi':1,'mardi':2,'mercredi':3,'jeudi':4,'vendredi':5,'samedi':6
  };
  for (const [n,num] of Object.entries(dias)) {
    if (s.includes(n)) { const d=new Date(hoy); let diff=(num-d.getDay()+7)%7; if(diff===0)diff=7; d.setDate(d.getDate()+diff); return fmt(d); }
  }

  // día del mes suelto: "el 23", "23"
  m = s.match(/\b(\d{1,2})\b/);
  if (m) {
    const dia = parseInt(m[1],10);
    if (dia>=1 && dia<=31) {
      let cand = new Date(hoy.getFullYear(), hoy.getMonth(), dia);
      if (cand < hoy) cand = new Date(hoy.getFullYear(), hoy.getMonth()+1, dia);
      if (!isNaN(cand) && cand.getDate()===dia) return fmt(cand);
    }
  }
  return '';
}

return [{ json: {
  fn,
  negocio_id,
  servicio: args.servicio ?? '',
  fecha: resolverFecha(args.fecha),
  fecha_original: args.fecha ?? '',
  hora: args.hora ?? '',
  nombre: args.nombre ?? 'cliente',
  confirmar: args.confirmar ?? '',
  from_number: call.from_number ?? '34000000000',
  fecha_nueva: resolverFecha(args.fecha_nueva),
  hora_nueva: args.hora_nueva ?? '',
  servicio_nuevo: args.servicio_nuevo ?? '',
  fecha_hasta: '',
  profesional: '',
  accion: ''
}}];

// Limpia el `response` del Motor (pensado para chat/LLM) para leerlo por voz (TTS).
let t = String($json.response ?? '');
// 1) prefijo tecnico al inicio (OCUPADO:, CONFIRMAR:, NO_ENCONTRADA:, FALTA_NOMBRE:, etc.)
t = t.replace(/^[A-Z_]{3,}:s*/, '');
// 2) markdown de negrita / asteriscos
t = t.replace(/*+/g, '');
// 3) emojis y simbolos
t = t.replace(/[🀀-🫿☀-➿←-⇿⬀-⯿️]/gu, '');
// 4) 'la h' pegada a la hora: 09:00h -> 09:00
t = t.replace(/(d{1,2}:d{2})s*h /g, '$1');
// 5) espacios sobrantes
t = t.replace(/[ 	]{2,}/g, ' ').replace(/s*
s*/g, '. ').trim();
return [{ json: { response: t } }];
